mapper.select:
SELECT

FROM TBL_SUBJECT_BALANCE


        AND BOOK_ID = #{param.bookId}


        AND TENANT_ID = #{param.tenantId}


        AND SUBJECT_CODE = #{param.subjectCode}


        AND SUBJECT_NAME LIKE CONCAT('%', #{param.subjectName}, '%')


        AND ACCOUNTING_PERIOD = #{param.accountingPeriod}


        AND BALANCE_DIRECTION = #{param.balanceDirection}


ORDER BY SUBJECT_CODE

SELECT COUNT(1)
FROM TBL_SUBJECT_BALANCE


        AND BOOK_ID = #{param.bookId}


        AND TENANT_ID = #{param.tenantId}


        AND SUBJECT_CODE = #{param.subjectCode}


        AND SUBJECT_NAME LIKE CONCAT('%', #{param.accountName}, '%')


        AND ACCOUNTING_PERIOD = #{param.accountingPeriod}


        AND BALANCE_DIRECTION = #{param.balanceDirection}

SELECT

FROM TBL_SUBJECT_BALANCE
WHERE SUBJECT_CODE = #{subjectCode}
AND ACCOUNTING_PERIOD = #{period}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

SELECT
    #{subjectCode} as subjectCode,
    s.SUBJECT_NAME as subjectName,
    #{period} as period,
    COALESCE(b.BEGINNING_BALANCE, 0) as beginningBalance,
    COALESCE(gl.periodDebit, 0) as currentDebit,
    COALESCE(gl.periodCredit, 0) as currentCredit,
    COALESCE(b.BEGINNING_BALANCE, 0) + COALESCE(gl.periodDebit, 0) - COALESCE(gl.periodCredit, 0) as endingBalance,
    s.BALANCE_DIRECTION as balanceDirection
FROM T_ACCOUNT_SUBJECT s
LEFT JOIN TBL_SUBJECT_BALANCE b ON s.SUBJECT_CODE = b.SUBJECT_CODE AND b.ACCOUNTING_PERIOD = #{period}
LEFT JOIN (
    SELECT
        ACCOUNT_CODE,
        SUM(DEBIT_AMOUNT) as periodDebit,
        SUM(CREDIT_AMOUNT) as periodCredit
    FROM TBL_GENERAL_LEDGER
    WHERE ACCOUNT_CODE = #{subjectCode}
    AND ACCOUNTING_PERIOD = #{period}
    AND BOOK_ID = #{bookId}
    AND TENANT_ID = #{tenantId}
    GROUP BY ACCOUNT_CODE
) gl ON s.SUBJECT_CODE = gl.ACCOUNT_CODE
WHERE s.SUBJECT_CODE = #{subjectCode}
AND s.BOOK_ID = #{bookId}
AND s.TENANT_ID = #{tenantId}

SELECT COALESCE(ENDING_BALANCE, 0)
FROM TBL_SUBJECT_BALANCE
WHERE SUBJECT_ID = #{subjectId}
AND ACCOUNTING_PERIOD = (
    SELECT MAX(ACCOUNTING_PERIOD)
    FROM TBL_SUBJECT_BALANCE
    WHERE SUBJECT_ID = #{subjectId}
    AND ACCOUNTING_PERIOD < #{period}
    AND BOOK_ID = #{bookId}
    AND TENANT_ID = #{tenantId}
)
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

SELECT
    SUM(DEBIT_AMOUNT) as debitAmount,
    SUM(CREDIT_AMOUNT) as creditAmount
FROM TBL_GENERAL_LEDGER
WHERE ACCOUNT_CODE = #{subjectCode}
AND ACCOUNTING_PERIOD = #{period}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

choose.when:
MERGE INTO TBL_SUBJECT_BALANCE t USING ( SELECT s.SUBJECT_ID, s.SUBJECT_CODE, s.SUBJECT_NAME, #{param.period} as ACCOUNTING_PERIOD, COALESCE( (SELECT ENDING_BALANCE FROM TBL_SUBJECT_BALANCE WHERE SUBJECT_CODE = s.SUBJECT_CODE AND ACCOUNTING_PERIOD = ( SELECT MAX(ACCOUNTING_PERIOD) FROM TBL_SUBJECT_BALANCE WHERE SUBJECT_CODE = s.SUBJECT_CODE AND ACCOUNTING_PERIOD < #{param.period} ) AND BOOK_ID = s.BOOK_ID AND TENANT_ID = s.TENANT_ID LIMIT 1), 0 ) as BEGINNING_BALANCE, COALESCE(gl.periodDebit, 0) as PERIOD_DEBIT_AMOUNT, COALESCE(gl.periodCredit, 0) as PERIOD_CREDIT_AMOUNT, COALESCE( (SELECT ENDING_BALANCE FROM TBL_SUBJECT_BALANCE WHERE SUBJECT_CODE = s.SUBJECT_CODE AND ACCOUNTING_PERIOD = ( SELECT MAX(ACCOUNTING_PERIOD) FROM TBL_SUBJECT_BALANCE WHERE SUBJECT_CODE = s.SUBJECT_CODE AND ACCOUNTING_PERIOD < #{param.period} ) AND BOOK_ID = s.BOOK_ID AND TENANT_ID = s.TENANT_ID LIMIT 1), 0 ) + COALESCE(gl.periodDebit, 0) - COALESCE(gl.periodCredit, 0) as ENDING_BALANCE, s.BALANCE_DIRECTION, s.BOOK_ID, s.TENANT_ID FROM T_ACCOUNT_SUBJECT s LEFT JOIN ( SELECT ACCOUNT_CODE, SUM(DEBIT_AMOUNT) as periodDebit, SUM(CREDIT_AMOUNT) as periodCredit FROM TBL_GENERAL_LEDGER WHERE ACCOUNT_CODE = #{param.subjectCode} AND ACCOUNTING_PERIOD = #{param.period}
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
GROUP BY ACCOUNT_CODE ) gl ON s.SUBJECT_CODE = gl.ACCOUNT_CODE WHERE s.SUBJECT_CODE = #{param.subjectCode}
AND s.BOOK_ID = #{param.bookId}
AND s.TENANT_ID = #{param.tenantId}
) src ON (t.SUBJECT_CODE = src.SUBJECT_CODE AND t.ACCOUNTING_PERIOD = src.ACCOUNTING_PERIOD AND t.BOOK_ID = src.BOOK_ID AND t.TENANT_ID = src.TENANT_ID) WHEN MATCHED THEN UPDATE SET t.BEGINNING_BALANCE = src.BEGINNING_BALANCE, t.PERIOD_DEBIT_AMOUNT = src.PERIOD_DEBIT_AMOUNT, t.PERIOD_CREDIT_AMOUNT = src.PERIOD_CREDIT_AMOUNT, t.ENDING_BALANCE = src.ENDING_BALANCE, t.UPDATED_TIME = CURRENT_TIMESTAMP WHEN NOT MATCHED THEN INSERT ( SUBJECT_ID, SUBJECT_CODE, SUBJECT_NAME, ACCOUNTING_PERIOD, BEGINNING_BALANCE, PERIOD_DEBIT_AMOUNT, PERIOD_CREDIT_AMOUNT, ENDING_BALANCE, BALANCE_DIRECTION, BOOK_ID, TENANT_ID, CREATED_TIME ) VALUES ( src.SUBJECT_ID, src.SUBJECT_CODE, src.SUBJECT_NAME, src.ACCOUNTING_PERIOD, src.BEGINNING_BALANCE, src.PERIOD_DEBIT_AMOUNT, src.PERIOD_CREDIT_AMOUNT, src.ENDING_BALANCE, src.BALANCE_DIRECTION, src.BOOK_ID, src.TENANT_ID, CURRENT_TIMESTAMP )

mapper.delete:
DELETE FROM TBL_SUBJECT_BALANCE
WHERE ACCOUNTING_PERIOD = #{period}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

mapper.update:
-- 删除现有余额
DELETE FROM TBL_SUBJECT_BALANCE
WHERE ACCOUNTING_PERIOD = #{period}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId};

-- 重新计算并插入余额
INSERT INTO TBL_SUBJECT_BALANCE (
    SUBJECT_ID, SUBJECT_CODE, SUBJECT_NAME, ACCOUNTING_PERIOD,
    BEGINNING_BALANCE, PERIOD_DEBIT_AMOUNT, PERIOD_CREDIT_AMOUNT,
    ENDING_BALANCE, BALANCE_DIRECTION, BOOK_ID, TENANT_ID, CREATED_TIME
)
SELECT
    s.SUBJECT_ID,
    s.SUBJECT_CODE,
    s.SUBJECT_NAME,
    #{period} as ACCOUNTING_PERIOD,
    COALESCE(prev.ENDING_BALANCE, 0) as BEGINNING_BALANCE,
    COALESCE(curr.periodDebit, 0) as PERIOD_DEBIT_AMOUNT,
    COALESCE(curr.periodCredit, 0) as PERIOD_CREDIT_AMOUNT,
    COALESCE(prev.ENDING_BALANCE, 0) + COALESCE(curr.periodDebit, 0) - COALESCE(curr.periodCredit, 0) as ENDING_BALANCE,
    s.BALANCE_DIRECTION,
    s.BOOK_ID,
    s.TENANT_ID,
    CURRENT_TIMESTAMP
FROM T_ACCOUNT_SUBJECT s
LEFT JOIN (
    SELECT
        ACCOUNT_CODE,
        SUM(DEBIT_AMOUNT) as periodDebit,
        SUM(CREDIT_AMOUNT) as periodCredit
    FROM TBL_GENERAL_LEDGER
    WHERE ACCOUNTING_PERIOD = #{period}
    AND BOOK_ID = #{bookId}
    AND TENANT_ID = #{tenantId}
    GROUP BY ACCOUNT_CODE
) curr ON s.SUBJECT_CODE = curr.ACCOUNT_CODE
LEFT JOIN (
    SELECT DISTINCT
        SUBJECT_CODE,
        ENDING_BALANCE
    FROM TBL_SUBJECT_BALANCE b1
    WHERE b1.ACCOUNTING_PERIOD = (
        SELECT MAX(ACCOUNTING_PERIOD)
        FROM TBL_SUBJECT_BALANCE
        WHERE ACCOUNTING_PERIOD < #{period}
        AND BOOK_ID = #{bookId}
        AND TENANT_ID = #{tenantId}
    )
    AND BOOK_ID = #{bookId}
    AND TENANT_ID = #{tenantId}
) prev ON s.SUBJECT_CODE = prev.SUBJECT_CODE
WHERE s.BOOK_ID = #{bookId}
AND s.TENANT_ID = #{tenantId}
AND (curr.periodDebit IS NOT NULL OR curr.periodCredit IS NOT NULL OR prev.ENDING_BALANCE IS NOT NULL)

mapper.select:
SELECT
    COUNT(1) as subjectCount,
    SUM(CASE WHEN BALANCE_DIRECTION = '借方' THEN ENDING_BALANCE ELSE 0 END) as totalDebitBalance,
    SUM(CASE WHEN BALANCE_DIRECTION = '贷方' THEN ENDING_BALANCE ELSE 0 END) as totalCreditBalance,
    SUM(PERIOD_DEBIT_AMOUNT) as totalPeriodDebit,
    SUM(PERIOD_CREDIT_AMOUNT) as totalPeriodCredit
FROM TBL_SUBJECT_BALANCE
WHERE ACCOUNTING_PERIOD = #{period}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
